rsql with p as (select lp.season s, case when lp.person__player__position in ('OT','IOL') then 'OL' when lp.person__player__position in ('DT','EDGE') then 'DL' when lp.person__player__position in ('CB','S') then 'DB' else lp.person__player__position end u, more('log_players', lp._more) m from log_players lp where lp.level = 'NFL' and lp.overall >= 74 and ((lp.season between 2025 and 2027) or (lp.season between 2032 and 2034)) and lp.person__player__position in ('OT','IOL')) select u, a.key idx, round(avg(case when s <= 2027 then a.value end)/10,1) early, round(avg(case when s >= 2032 then a.value end)/10,1) late, round((avg(case when s >= 2032 then a.value end)-avg(case when s <= 2027 then a.value end))/10,2) diff from p, json_each(p.m, '$.person.player.attributes_x10') a group by u, idx order by u, idx
